import dev.hua.ptcglive.engine.effect.*;
import java.util.*;

/** Draft primitive tests; not a claim that Backtrack Badge is integrated. */
public final class AttackCoinSequenceTest {
    static class Context implements EffectExecutionContext {
        final ArrayDeque<Boolean> coins=new ArrayDeque<>();final List<String> operations=new ArrayList<>();int count;
        Context(boolean...values){for(boolean value:values)coins.add(value);}
        public CoinResult flipCoins(EffectDefinition e,int n){throw new AssertionError("Missing audit operation");}
        public CoinResult flipCoins(EffectDefinition e,int n,String op){check(n==1,"Not a single flip");operations.add(op);return new CoinResult(1,coins.remove()?1:0);}
        public int number(ConditionType t,EffectTarget x,Map<String,String> a){return count;}
        public boolean hasStatus(EffectTarget t,String s){return false;}
        public boolean flag(ConditionType t,EffectTarget x,Map<String,String> a){return false;}
        public boolean coinResult(String e){return false;}
        public boolean customCondition(ConditionDefinition c){return false;}
        public int choose(EffectDefinition e,int n){throw new AssertionError("No client randomness");}
        public void executeAtomic(EffectDefinition e){throw new AssertionError("No effects before confirmed result");}
    }
    static EffectDefinition effect(Map<String,String> args){return new EffectDefinition("coin_flip",EffectTarget.SELF,args,List.of(),List.of());}
    static AttackCoinSequence fixed(Context c,int n){return new AttackCoinSequence(effect(Map.of("flips",""+n)),c);}
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    static void reject(Runnable r){try{r.run();throw new AssertionError("Unexpected acceptance");}catch(IllegalArgumentException|IllegalStateException expected){}}
    static void decide(AttackCoinSequence s,AttackCoinSequence.Decision d){s.decide(s.prompt().revision(),d);}
    public static void main(String[] args){earlyRetry();lastRetry();keep();untilTails();dynamicAndEmpty();longSequences();authority();failure();System.out.println("AttackCoinSequenceTest passed: early/final optional retry, whole sequence reset, until tails, frozen dynamic count, zero flips, stale/repeated choices and failed-source lock; server integration is verified separately by AttackCoinMatchTest");}
    static void earlyRetry(){var c=new Context(false,true,false);var s=fixed(c,2);s.advance(true);check(c.operations.size()==1&&s.prompt().flips()==1&&!s.prompt().sequenceFinished(),"No early decision");reject(s::result);decide(s,AttackCoinSequence.Decision.RETRY);s.advance(true);check(s.complete()&&s.retried()&&s.prompt()==null&&s.result().heads()==1&&s.result().flips()==2&&c.operations.equals(List.of("attack-original:0","attack-retry:0","attack-retry:1")),"Retry retained original first flip or offered second retry");}
    static void lastRetry(){var c=new Context(true,false,false,false);var s=fixed(c,2);s.advance(true);decide(s,AttackCoinSequence.Decision.CONTINUE);s.advance(true);check(s.prompt().sequenceFinished()&&s.prompt().heads()==1,"Last decision unavailable");decide(s,AttackCoinSequence.Decision.RETRY);s.advance(true);check(s.result().heads()==0&&c.operations.size()==4,"Last retry retained first result");}
    static void keep(){var c=new Context(true,false,true);var s=fixed(c,3);s.advance(true);decide(s,AttackCoinSequence.Decision.FINISH_SEQUENCE);s.advance(true);check(s.prompt().sequenceFinished()&&s.prompt().flips()==3&&!s.complete(),"Finish skipped final retry opportunity");reject(()->decide(s,AttackCoinSequence.Decision.FINISH_SEQUENCE));decide(s,AttackCoinSequence.Decision.CONTINUE);s.advance(true);check(s.result().heads()==2&&!s.retried(),"Keeping results used retry");s.advance(true);check(c.operations.size()==3,"Completed sequence rerolled");}
    static void untilTails(){var c=new Context(true,true,false,true,false);var s=new AttackCoinSequence(effect(Map.of("until","TAILS")),c);s.advance(true);decide(s,AttackCoinSequence.Decision.FINISH_SEQUENCE);s.advance(true);check(s.prompt().flips()==3&&s.prompt().heads()==2,"Until tails initial sequence");decide(s,AttackCoinSequence.Decision.RETRY);s.advance(true);check(s.result().flips()==2&&s.result().heads()==1&&c.operations.size()==5,"Until tails retried fixed old count");var c2=new Context(true,false);var s2=new AttackCoinSequence(effect(Map.of("until","TAILS")),c2);s2.advance(true);decide(s2,AttackCoinSequence.Decision.RETRY);s2.advance(true);check(s2.result().flips()==1&&s2.result().heads()==0,"Early until-tails reset lost first tails");}
    static void dynamicAndEmpty(){var c=new Context(true,false,true,true);c.count=2;var e=effect(Map.of("flips","0","flips_from","ENERGY_COUNT","flips_target","SELF"));var s=new AttackCoinSequence(e,c);s.advance(true);c.count=0;decide(s,AttackCoinSequence.Decision.RETRY);s.advance(true);check(s.result().flips()==2&&c.operations.size()==3,"Retry recomputed count");var empty=new AttackCoinSequence(e,new Context());empty.advance(true);check(empty.complete()&&empty.prompt()==null&&empty.result().flips()==0,"Zero flips prompted retry");var c2=new Context(false,true);var auto=fixed(c2,2);auto.advance(false);check(auto.result().heads()==1&&auto.prompt()==null,"Ineligible sequence prompted");}
    static void longSequences(){var c=new Context();c.count=70;for(int i=0;i<140;i++)c.coins.add(i%2==0);var s=new AttackCoinSequence(effect(Map.of("flips","0","flips_from","ENERGY_COUNT","flips_target","SELF")),c);s.advance(true);decide(s,AttackCoinSequence.Decision.FINISH_SEQUENCE);s.advance(true);check(s.prompt().flips()==70,"Dynamic sequence truncated at20");decide(s,AttackCoinSequence.Decision.RETRY);s.advance(true);check(s.result().flips()==70&&s.result().heads()==35&&c.operations.size()==140,"Large retry incomplete");var u=new Context();for(int i=0;i<30;i++)u.coins.add(true);u.coins.add(false);u.coins.add(false);var t=new AttackCoinSequence(effect(Map.of("until","TAILS")),u);t.advance(true);decide(t,AttackCoinSequence.Decision.FINISH_SEQUENCE);t.advance(true);check(t.prompt().flips()==31&&t.prompt().heads()==30,"Until tails capped at20");decide(t,AttackCoinSequence.Decision.RETRY);t.advance(true);check(t.result().flips()==1&&t.result().heads()==0&&u.operations.size()==32,"Long sequence not fully reset");}
    static void authority(){var c=new Context(true,false);var s=fixed(c,2);reject(()->s.decide(1,AttackCoinSequence.Decision.RETRY));s.advance(true);var p=s.prompt();reject(()->s.decide(p.revision()+1,AttackCoinSequence.Decision.RETRY));check(s.prompt().equals(p)&&c.operations.size()==1,"Stale choice mutated state");s.advance(true);check(c.operations.size()==1,"Pending prompt rerolled");decide(s,AttackCoinSequence.Decision.CONTINUE);reject(()->s.decide(p.revision(),AttackCoinSequence.Decision.RETRY));s.advance(true);reject(()->s.decide(p.revision(),AttackCoinSequence.Decision.RETRY));check(c.operations.size()==2,"Replay consumed RNG");reject(()->new AttackCoinSequence(effect(Map.of("flips","2","reroll","TAILS_ONCE")),c));}
    static void failure(){var c=new Context();var s=fixed(c,1);try{s.advance(true);throw new AssertionError("Missing failure");}catch(NoSuchElementException expected){}reject(()->s.advance(true));reject(s::result);check(c.operations.size()==1,"Failed source silently replayed");}
}
